const copiar=async t=>{try{await navigator.clipboard.writeText(t);aviso('Copiado.')}catch(e){const x=document.createElement('textarea');x.value=t;document.body.appendChild(x);x.select();try{document.execCommand('copy');aviso('Copiado.')}catch(z){aviso('No se pudo copiar.')}x.remove()}};
const nota=(t,x)=>window.NX&&NX.nota?NX.nota(t,x):aviso('El anotador no está disponible.');
const bajarTxt=(nom,txt,tipo)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:tipo||'text/plain;charset=utf-8'}));a.download=nom;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)};
const VIEWS=[['panel','Panel'],['buscar','Buscar'],['est','Estimaciones'],['contra','Contradicciones'],['red','Red'],['fuentes','Fuentes'],['cargar','Cargar datos'],['informe','Informe e IA']];
function paint(keepFocus){const el=document.getElementById('int');if(!el||!D)return;const act=document.activeElement,fid=keepFocus&&act&&act.id==='intq'?{p:act.selectionStart}:null,y=scrollY;
 let body='';try{body={panel:vPanel,buscar:vBuscar,est:vEst,contra:vContra,red:vRed,fuentes:vFuentes,cargar:vCargar,informe:vInforme}[ST.v]()}catch(e){console.error('NEWAR Inteligencia',e);body='<p class="warn" role="alert">No se pudo armar esta sección. Probá recargar la página.</p>'}
 el.innerHTML=`<div class="ctl" role="group" aria-label="Secciones de Inteligencia">${VIEWS.map(([k,l])=>`<button type="button" class="${ST.v===k?'on':''}" data-i="v:${k}" aria-pressed="${ST.v===k}">${l}</button>`).join('')}</div><div class="ctl"><span class="meta">Tolerancia:</span>${segb('tol',[[.5,'Estricta'],[1,'Normal'],[2,'Laxa']],ST.tol)}<label class="meta">Ventana <select aria-label="Ventana de fechas" data-sel="win">${[[60,'60 días'],[180,'180 días'],[365,'1 año'],[9999,'Todo']].map(([v,t])=>sel(v,t,ST.win)).join('')}</select></label></div>`+body;
 if(ST.v==='red')drawRed(false);
 if(fid){const q=document.getElementById('intq');if(q){q.focus();try{q.setSelectionRange(fid.p,fid.p)}catch(e){}}}else window.scrollTo(0,y)}
const cargarD=()=>LOAD||(LOAD=Promise.all([leer('consultoras'),leer('consultoras_news')]).then(([d,n])=>{D=d&&typeof d==='object'?d:{fuentes:[],cifras:[],indicadores:[]};NW=n&&n.items?n:{items:[]};reset()}));
const filtPar=p=>(!ST.ind||p.ind===ST.ind)&&(!ST.tipo||FU(p.a.fuente).tipo===ST.tipo||FU(p.b.fuente).tipo===ST.tipo);
function accion(a,v,e){const go=()=>{paint();window.scrollTo(0,0)};
 switch(a){
 case'v':ST.v=v;ST.n=40;go();break;
 case'tol':ST.tol=+v;reset();paint();break;
 case'ficha':ST.sel=v;ST.v='fuentes';go();break;
 case'enred':ST.sel=v;ST.v='red';go();break;
 case'ind':ST.ei=v;ST.v='est';go();break;
 case'q':Object.assign(ST,{q:v,kind:'',tipo:'',pais:'',ind:'',v:'buscar',n:40});go();break;
 case'visto':lsSet(VK,Date.now());paint();break;
 case'mas':ST.n+=40;paint();break;
 case'k':ST.k=v;ST.n=40;paint();break;
 case'capa':ST.capa[v]=e.target.checked?1:0;drawRed(true);break;
 case'csvbusq':{const rs=buscaTodo();if(!rs)return;const rows=[['tipo','nombre o título','detalle','fecha','enlace']];rs.R.f.forEach(f=>rows.push(['fuente',f.nombre,f.tipo+' · '+(f.pais||''),'',f.sitio||'']));rs.R.c.forEach(c=>rows.push(['cifra',IND(c.ind).t+': '+num(c.valor,IND(c.ind).u),FU(c.fuente).nombre,c.fecha,c.url||'']));rs.R.n.forEach(n=>rows.push(['nota',n.title,FU(n.fuente).nombre,n.published_iso||'',n.link||'']));bajarCSV('busqueda-fuentes.csv',rows);break}
 case'csvest':{const g=grupos().find(x=>x.ind===ST.ei);if(!g)return;bajarCSV('estimaciones-'+slug(g.def.t)+'.csv',[['fuente','tipo','valor','unidad','fecha','mediana','diferencia','veredicto','enlace']].concat(g.L.map(c=>[FU(c.fuente).nombre,FU(c.fuente).tipo,c.valor,g.def.u,c.fecha,g.med,c.valor-g.med,verd(Math.abs(c.valor-g.med),g.thr),c.url||''])));break}
 case'csvpares':bajarCSV('pares-fuentes.csv',[['indicador','fuente A','valor A','fecha A','fuente B','valor B','fecha B','brecha','veces el umbral','veredicto']].concat(pares().filter(filtPar).map(p=>[p.def.t,FU(p.a.fuente).nombre,p.a.valor,p.a.fecha,FU(p.b.fuente).nombre,p.b.valor,p.b.fecha,p.d,p.r,p.v])));break;
 case'csvcons':bajarCSV('consenso-indicadores.csv',[['indicador','grupo','unidad','fuentes','mediana','promedio','mínimo','máximo','umbral']].concat(grupos().filter(g=>g.n).map(g=>[g.def.t,g.def.g,g.def.u,g.n,g.med,g.mean,g.min,g.max,g.thr])));break;
 case'csvcif':bajarCSV('cifras-con-fuente.csv',[['indicador','fuente','tipo','valor','unidad','fecha','enlace','detalle','cargada por el usuario']].concat(CIF().map(c=>[IND(c.ind).t,FU(c.fuente).nombre,FU(c.fuente).tipo,c.valor,IND(c.ind).u,c.fecha,c.url||'',c.detalle||'',c.propia?'sí':'no'])));break;
 case'notaest':{const g=grupos().find(x=>x.ind===ST.ei);if(!g)return;nota('Estimaciones · '+g.def.t,g.def.t+' ('+g.n+' fuentes): mediana '+num(g.med,g.def.u)+', rango '+f1(g.min)+'–'+f1(g.max)+'.\n'+g.L.map(c=>'- '+FU(c.fuente).nombre+': '+num(c.valor,g.def.u)+' ('+fF(c.fecha)+')'+(c.url?' '+c.url:'')).join('\n'));break}
 case'notaf':{const P=perfil(v);nota('Fuente · '+P.f.nombre,P.f.nombre+' ('+P.f.tipo+'): '+P.cs.length+' cifras; coincide en '+P.coin+' pares y se contradice en '+P.cont+'.\n'+P.cs.map(c=>'- '+IND(c.ind).t+': '+num(c.valor,IND(c.ind).u)+' ('+fF(c.fecha)+')').join('\n'));break}
 case'add':{const g=id=>(document.getElementById(id)||{}).value||'';const r=agregar({fuente:g('cf-f'),ind:g('cf-i'),valor:g('cf-v'),u:g('cf-u'),fecha:g('cf-d'),url:g('cf-url'),detalle:g('cf-n')});if(!r){aviso('Completá la fuente y un valor numérico.');return}if(r.url&&!/^https?:\/\//i.test(r.url)){aviso('El enlace tiene que empezar con http:// o https://');return}const l=propias();l.push(r);guardar(l);reset();aviso('Cifra agregada. Ya entra en los cruces.');paint();break}
 case'imp':{const t=(document.getElementById('cf-csv')||{}).value||'';const lines=t.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!lines.length){aviso('Pegá al menos una fila.');return}const sep=lines[0].includes(';')?';':lines[0].includes('\t')?'\t':',';let ok=0,mal=0;const l=propias();lines.forEach(s=>{const c=s.split(sep).map(x=>x.trim().replace(/^"|"$/g,''));if(/^indicador/i.test(fold(c[0]))&&isNaN(dec(c[2])))return;const r=agregar({ind:c[0],fuente:c[1],valor:c[2],fecha:c[3],url:c[4],detalle:c[5]});if(r&&(!r.url||/^https?:\/\//i.test(r.url))){l.push(r);ok++}else mal++});guardar(l);reset();aviso('Se importaron '+ok+' cifra'+(ok===1?'':'s')+(mal?' ('+mal+' fila'+(mal===1?'':'s')+' sin valor, sin fuente o con enlace inválido)':'')+'.');paint();break}
 case'plant':bajarCSV('plantilla-cifras.csv',[['indicador','fuente','valor','fecha','enlace','detalle'],['Inflación 2026','Goldman Sachs','29','2026-10-08','https://…','Informe semanal']]);break;
 case'del':guardar(propias().filter(x=>x.id!==v));reset();paint();break;
 case'delall':if(confirm('¿Borrar todas las cifras que cargaste? No se puede deshacer.')){guardar([]);reset();paint()}break;
 case'expjson':bajarTxt('cifras-propias.json',JSON.stringify(propias().map(c=>{const o=Object.assign({},c);delete o.id;return o}),null,1),'application/json');break;
 case'informe':ST.para=(document.getElementById('inf-p')||{}).value||'';informe();break;
 case'ia':{ST.msg=(document.getElementById('inf-m')||{}).value||'';const t=promptIA(),x=document.getElementById('inf-t');if(x){x.value=t;const n=document.getElementById('inf-n');if(n)n.textContent=t.length.toLocaleString('es-AR')+' caracteres';x.focus();x.select()}break}
 case'iacopy':{let x=document.getElementById('inf-t');if(x&&!x.value){ST.msg=(document.getElementById('inf-m')||{}).value||'';x.value=promptIA()}if(x)copiar(x.value);break}
 }}
if(!window._intWired){window._intWired=1;
 document.addEventListener('click',e=>{const box=e.target.closest&&e.target.closest('#int');if(!box)return;const nd=e.target.closest('#intbox g.nd');if(nd){ST.sel=ST.sel===nd.dataset.id?'':nd.dataset.id;hlRed(ST.sel);detRed();return}
  const b=e.target.closest('[data-i]');if(!b)return;if(b.tagName==='A')e.preventDefault();const s=b.dataset.i,i=s.indexOf(':');try{accion(s.slice(0,i),s.slice(i+1),e)}catch(x){console.error('NEWAR Inteligencia',s,x)}});
 document.addEventListener('change',e=>{const t=e.target.closest&&e.target.closest('#int [data-sel]');if(!t)return;const k=t.dataset.sel;ST[k]=k==='win'?+t.value:t.value;if(k==='win')reset();ST.n=40;paint()});
 let tq=0;document.addEventListener('input',e=>{const t=e.target;if(!t||!t.closest||!t.closest('#int'))return;if(t.id==='intq'){clearTimeout(tq);tq=setTimeout(()=>{ST.q=t.value;ST.n=40;paint(true)},260)}else if(t.id==='inf-m')ST.msg=t.value;else if(t.id==='inf-p')ST.para=t.value});
 document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='intq'){clearTimeout(tq);ST.q=e.target.value;paint(true)}})}
const iC=TABS.findIndex(t=>t[0]==='consultoras');if(!TABS.some(t=>t[0]==='inteligencia'))TABS.splice(iC>=0?iC+1:TABS.length,0,['inteligencia','Inteligencia']);
{const g=(typeof TGRP!=='undefined')&&TGRP.find(x=>x[0]==='Mapas y datos');if(g&&!g[1].includes('inteligencia'))g[1].push('inteligencia')}
if(typeof NEEDS!=='undefined')NEEDS.inteligencia=[];
const boot=()=>cargarD().then(()=>paint()).catch(e=>{console.error('NEWAR Inteligencia',e);const el=document.getElementById('int');if(el)el.innerHTML='<p class="warn" role="alert">No se pudieron cargar los datos de consultoras (data/consultoras.json).</p>'});
V.inteligencia=arg=>{if(arg&&arg!==ST._arg){ST._arg=arg;if(VIEWS.some(v=>v[0]===arg))ST.v=arg}setTimeout(boot);
 return'<h2 class="sec">Inteligencia de fuentes</h2><p class="lede">Cruza lo que dicen los bancos, las consultoras, los organismos y las encuestadoras: dónde <b>coinciden</b>, dónde se <b>contradicen</b>, quién <b>cambió</b> su cifra y qué fuentes se apartan del consenso, con una <b>red</b> que las conecta. Cada cifra lleva su fuente y su fecha; lo que no está cargado figura como «sin dato». Podés sumar tus propias cifras en «Cargar datos».</p><div id="int"><p class="note" role="status">Cargando…</p></div>'};
